    excerpt:
      "\u0627\u0644\u0628\u0631\u0627\u0642 \u064a\u0642\u0637\u0639 \u0637\u0646\u062c\u0629\u2013\u0627\u0644\u062f\u0627\u0631 \u0627\u0644\u0628\u064a\u0636\u0627\u0621 \u0641\u064a \u0633\u0627\u0639\u062a\u064a\u0646 \u0648\u0639\u0634\u0631 \u062f\u0642\u0627\u0626\u0642. \u0644\u0643\u0646 \u0644\u0627 \u0642\u0637\u0627\u0631 \u064a\u0635\u0644 \u0645\u0631\u0632\u0648\u0642\u0629 \u0623\u0648 \u0634\u0641\u0634\u0627\u0648\u0646 \u0623\u0648 \u0627\u0644\u0635\u0648\u064a\u0631\u0629 \u0623\u0648 \u0648\u0631\u0632\u0627\u0632\u0627\u062a \u2014 \u0648\u0647\u064a \u062d\u064a\u062b \u064a\u0631\u064a\u062f \u0623\u063a\u0644\u0628 \u0627\u0644\u0632\u0648\u0627\u0631 \u0627\u0644\u0630\u0647\u0627\u0628.",
